package com.greatleyposhley.professy.collaboration;

import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;
import static com.greatleyposhley.professy.collaboration.WorkAccess.number;

/** Project documents have one canonical record, shared by Docsy, chat and tickets. */
@RestController @RequestMapping("/api/workspace/documents")
public class WorkspaceDocumentsController {
 private final WorkAccess access;
 public WorkspaceDocumentsController(WorkAccess access){this.access=access;}
 private String text(Object value,int max){String text=Objects.toString(value,"").trim();if(text.length()>max)throw new IllegalArgumentException("Document field is too long");return text;}
 private String visibility(){return "(p.created_by=? OR EXISTS(SELECT 1 FROM document_shares sh WHERE sh.page_id=p.id AND sh.user_id=?))";}
 private boolean manager(Map<String,Object> row){return number(row.get("created_by"))==access.actor().getId();}
 private boolean canEdit(Map<String,Object> row){if(!access.policy.can(access.actor(),"DOCUMENTS.UPDATE"))return false;if(manager(row))return true;return access.jdbc.queryForObject("SELECT COUNT(*) FROM document_shares WHERE page_id=? AND user_id=? AND permission='EDITOR'",Integer.class,row.get("id"),access.actor().getId())>0;}
 private Map<String,Object> row(long id){
  access.require("DOCUMENTS.READ");var user=access.actor();
  var rows=access.jdbc.queryForList("SELECT p.*,m.revision,COALESCE(ds.general_access,'RESTRICTED') AS general_access,CAST(SUBSTRING(s.slug,9) AS UNSIGNED) AS project_id FROM doc_pages p JOIN doc_spaces s ON s.id=p.space_id AND s.org_id=p.org_id LEFT JOIN document_metadata m ON m.page_id=p.id LEFT JOIN document_sharing ds ON ds.page_id=p.id WHERE p.id=? AND p.org_id=? AND s.slug REGEXP '^project-[0-9]+$' AND "+visibility(),id,user.getOrgId(),user.getId(),user.getId());
  if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Document not found or not shared with you");var row=rows.getFirst();access.project(number(row.get("project_id")));return row;
 }
 private Map<String,Object> view(Map<String,Object> row,boolean content){
  var result=new LinkedHashMap<String,Object>();
  for(String[] pair:List.of(new String[]{"id","id"},new String[]{"projectId","project_id"},new String[]{"title","title"},new String[]{"status","status"},new String[]{"updatedAt","updated_at"},new String[]{"createdAt","created_at"},new String[]{"createdBy","created_by"},new String[]{"format","content_format"}))result.put(pair[0],row.get(pair[1]));
  result.put("revision",row.get("revision")==null?1:row.get("revision"));result.put("canEdit",canEdit(row));result.put("canShare",manager(row));result.put("generalAccess",Objects.toString(row.get("general_access"),"RESTRICTED"));
  var author=access.jdbc.queryForList("SELECT CONCAT_WS(' ',first_name,last_name) AS name,profile_picture_url AS avatar FROM user_account WHERE id=? AND org_id=?",row.get("created_by"),access.actor().getOrgId());result.put("author",author.isEmpty()?Map.of("name","Former member"):author.getFirst());
  result.put("tags",access.jdbc.queryForList("SELECT tag FROM document_tags WHERE page_id=? ORDER BY tag",String.class,row.get("id")));if(content)result.put("content",Objects.toString(row.get("content"),""));return result;
 }
 @GetMapping public Object list(@RequestParam long projectId,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String tag,@RequestParam(defaultValue="0")int offset){
  access.require("DOCUMENTS.READ");access.project(projectId);int start=Math.max(0,Math.min(offset,1000000));String term="%"+q.trim().replace("!","!!").replace("%","!%").replace("_","!_")+"%";var user=access.actor();
  var rows=access.jdbc.queryForList("SELECT p.*,m.revision,COALESCE(ds.general_access,'RESTRICTED') AS general_access,? AS project_id FROM doc_pages p JOIN doc_spaces s ON s.id=p.space_id AND s.org_id=p.org_id LEFT JOIN document_metadata m ON m.page_id=p.id LEFT JOIN document_sharing ds ON ds.page_id=p.id WHERE p.org_id=? AND s.slug=? AND p.title LIKE ? ESCAPE '!' AND (?='' OR EXISTS(SELECT 1 FROM document_tags t WHERE t.page_id=p.id AND t.tag=?)) AND "+visibility()+" ORDER BY p.updated_at DESC,p.id DESC LIMIT 25 OFFSET ?",projectId,user.getOrgId(),"project-"+projectId,term,tag,tag,user.getId(),user.getId(),start);
  boolean more=rows.size()>24;if(more)rows=rows.subList(0,24);return Map.of("items",rows.stream().map(r->view(r,false)).toList(),"nextOffset",more?start+24:-1);
 }
 @GetMapping("/tags")public Object tags(@RequestParam long projectId){access.require("DOCUMENTS.READ");access.project(projectId);var user=access.actor();return access.jdbc.queryForList("SELECT DISTINCT t.tag FROM document_tags t JOIN doc_pages p ON p.id=t.page_id JOIN doc_spaces s ON s.id=p.space_id LEFT JOIN document_sharing ds ON ds.page_id=p.id WHERE p.org_id=? AND s.slug=? AND "+visibility()+" ORDER BY t.tag",String.class,user.getOrgId(),"project-"+projectId,user.getId(),user.getId());}
 @GetMapping("/{id}")public Object get(@PathVariable long id){return view(row(id),true);}
 @PostMapping @Transactional public Object create(@RequestBody Map<String,Object> body){
  access.require("DOCUMENTS.CREATE");long project=number(body.get("projectId"));access.project(project);var actor=access.actor();access.jdbc.queryForList("SELECT id FROM projects WHERE id=? FOR UPDATE",project);
  var spaces=access.jdbc.queryForList("SELECT id FROM doc_spaces WHERE org_id=? AND slug=?",Long.class,actor.getOrgId(),"project-"+project);long space;
  if(spaces.isEmpty()){access.jdbc.update("INSERT INTO doc_spaces(org_id,user_id,name,slug,visibility,status,created_by) VALUES(?,?,?,?,'ORGANIZATION','ACTIVE',?)",actor.getOrgId(),actor.getId(),"Project documents","project-"+project,actor.getId());space=access.jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);}else space=spaces.getFirst();
  String title=text(body.getOrDefault("title","Untitled document"),255);if(title.isBlank())throw new IllegalArgumentException("Title is required");String content=text(body.get("content"),1000000);
  access.jdbc.update("INSERT INTO doc_pages(org_id,user_id,space_id,title,slug,content,content_format,page_type,status,sort_order,created_by,updated_by) VALUES(?,?,?,?,?,?,'HTML','GENERAL','DRAFT',0,?,?)",actor.getOrgId(),actor.getId(),space,title,"document-"+UUID.randomUUID(),content,actor.getId(),actor.getId());long id=access.jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);access.jdbc.update("INSERT IGNORE INTO document_metadata(page_id,revision) VALUES(?,1)",id);saveTags(id,body.get("tags"));snapshot(id,title,content,1);access.policy.event(actor,"DOCUMENT_UPDATED",0);return view(row(id),true);
 }
 @PutMapping("/{id}")@Transactional public Object save(@PathVariable long id,@RequestBody Map<String,Object> body){
  var before=row(id);if(!canEdit(before))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Editing is not allowed for this document");access.jdbc.queryForList("SELECT page_id FROM document_metadata WHERE page_id=? FOR UPDATE",id);var row=row(id);
  if(number(body.get("revision"))!=number(row.get("revision")))throw new ResponseStatusException(HttpStatus.CONFLICT,"This document changed in another tab. Reload the latest version before saving.");String title=text(body.get("title"),255),content=text(body.get("content"),1000000);if(title.isBlank())throw new IllegalArgumentException("Title is required");
  access.jdbc.update("UPDATE doc_pages SET title=?,content=?,content_format='HTML',updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND org_id=?",title,content,access.actor().getId(),id,access.actor().getOrgId());access.jdbc.update("INSERT INTO document_metadata(page_id,revision) VALUES(?,2) ON DUPLICATE KEY UPDATE revision=revision+1",id);saveTags(id,body.get("tags"));snapshot(id,title,content,number(row(id).get("revision")));access.policy.event(access.actor(),"DOCUMENT_UPDATED",0);return view(row(id),true);
 }
 private void saveTags(long id,Object value){if(!(value instanceof List<?> list))return;if(list.size()>20)throw new IllegalArgumentException("Use up to 20 tags");var tags=new TreeSet<String>();for(Object entry:list){String tag=text(entry,50).toLowerCase(Locale.ROOT);if(!tag.isBlank())tags.add(tag);}access.jdbc.update("DELETE FROM document_tags WHERE page_id=?",id);for(String tag:tags)access.jdbc.update("INSERT INTO document_tags(page_id,tag) VALUES(?,?)",id,tag);}
 private void snapshot(long id,String title,String content,long revision){access.jdbc.update("INSERT IGNORE INTO document_revisions(page_id,revision,title,content,saved_by) VALUES(?,?,?,?,?)",id,revision,title,content,access.actor().getId());}
 @GetMapping("/{id}/versions")public Object versions(@PathVariable long id){row(id);return access.jdbc.queryForList("SELECT r.revision,r.title,r.created_at,r.saved_by,CONCAT_WS(' ',u.first_name,u.last_name) AS authorName FROM document_revisions r LEFT JOIN user_account u ON u.id=r.saved_by WHERE r.page_id=? ORDER BY r.revision DESC LIMIT 100",id);}
 @GetMapping("/{id}/versions/{revision}")public Object version(@PathVariable long id,@PathVariable long revision){row(id);var rows=access.jdbc.queryForList("SELECT revision,title,content,created_at FROM document_revisions WHERE page_id=? AND revision=?",id,revision);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return rows.getFirst();}
 @GetMapping("/{id}/sharing")public Object sharing(@PathVariable long id){var row=row(id);if(!manager(row))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the owner can manage sharing");return Map.of("generalAccess",row.get("general_access"),"members",access.jdbc.queryForList("SELECT sh.user_id AS userId,sh.permission,CONCAT_WS(' ',u.first_name,u.last_name) AS name,u.email FROM document_shares sh JOIN user_account u ON u.id=sh.user_id WHERE sh.page_id=? AND u.org_id=? ORDER BY u.first_name",id,access.actor().getOrgId()));}
 @PutMapping("/{id}/sharing")@Transactional public Object share(@PathVariable long id,@RequestBody Map<String,Object> body){
  var doc=row(id);if(!manager(doc))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the owner can manage sharing");String mode="RESTRICTED";if(!(body.get("members") instanceof List<?> members)||members.size()>200)throw new IllegalArgumentException("Choose up to 200 members");
  access.jdbc.update("INSERT INTO document_sharing(page_id,general_access) VALUES(?,?) ON DUPLICATE KEY UPDATE general_access=VALUES(general_access)",id,mode);access.jdbc.update("DELETE FROM document_shares WHERE page_id=?",id);
  for(Object value:members){if(!(value instanceof Map<?,?> member))throw new IllegalArgumentException("Choose a member");long user=number(member.get("userId"));String permission=text(member.get("permission"),10);if(!Set.of("VIEWER","EDITOR").contains(permission)||access.jdbc.queryForObject("SELECT COUNT(*) FROM user_account WHERE id=? AND org_id=? AND is_active=1",Integer.class,user,access.actor().getOrgId())!=1)throw new IllegalArgumentException("Choose an active member and permission");access.jdbc.update("INSERT INTO document_shares(page_id,user_id,permission) VALUES(?,?,?) ON DUPLICATE KEY UPDATE permission=VALUES(permission)",id,user,permission);}
  access.policy.event(access.actor(),"DOCUMENT_UPDATED",0);return sharing(id);
 }
 @GetMapping("/{id}/comments")public Object comments(@PathVariable long id){row(id);return access.jdbc.queryForList("SELECT c.id,c.author_id AS authorId,c.content,c.resolved,c.created_at AS createdAt,CONCAT_WS(' ',u.first_name,u.last_name) AS authorName FROM document_comments c JOIN user_account u ON u.id=c.author_id WHERE c.page_id=? AND c.org_id=? ORDER BY c.id",id,access.actor().getOrgId());}
 @PostMapping("/{id}/comments")@Transactional public Object comment(@PathVariable long id,@RequestBody Map<String,Object> body){row(id);String content=text(body.get("content"),20000);if(content.isEmpty())throw new IllegalArgumentException("Write a comment");access.jdbc.update("INSERT INTO document_comments(page_id,org_id,author_id,content) VALUES(?,?,?,?)",id,access.actor().getOrgId(),access.actor().getId(),content);access.policy.event(access.actor(),"DOCUMENT_UPDATED",0);return comments(id);}
 @PutMapping("/{id}/comments/{comment}")@Transactional public Object resolve(@PathVariable long id,@PathVariable long comment,@RequestBody Map<String,Object> body){var doc=row(id);int count=access.jdbc.update("UPDATE document_comments SET resolved=? WHERE id=? AND page_id=? AND org_id=? AND author_id=?",Boolean.TRUE.equals(body.get("resolved")),comment,id,access.actor().getOrgId(),access.actor().getId());if(count==0)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the author can resolve this comment");access.policy.event(access.actor(),"DOCUMENT_UPDATED",0);return comments(id);}
 @DeleteMapping("/{id}")@Transactional public void delete(@PathVariable long id){access.require("DOCUMENTS.DELETE");if(!manager(row(id)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the owner can delete this document");var actor=access.actor();for(String table:List.of("document_shares","document_sharing","document_comments","document_metadata","document_tags","document_revisions"))access.jdbc.update("DELETE FROM "+table+" WHERE page_id=?",id);access.jdbc.update("DELETE FROM ticket_documents WHERE document_id=? AND org_id=?",id,actor.getOrgId());access.jdbc.update("DELETE FROM doc_pages WHERE id=? AND org_id=?",id,actor.getOrgId());access.policy.event(actor,"DOCUMENT_UPDATED",0);}
}
